// Generated by scripts/build_faker_data.py from db/*.csv — regenerate, don't hand-edit faker.json
import data from "./faker.json";

export interface FakerGame {
  win: boolean;
  side: string; // "Blue" | "Red"
  champion: string;
  duration: string; // "mm:ss"
  k: number | null;
  d: number | null;
  a: number | null;
  cs: number | null;
  gold: number | null;
  damage: number | null;
  teamKills: number | null;
  patch: string | null;
  keystone: string | null;
  items: string[];
}

export interface FakerSeries {
  date: string;
  tournament: string;
  round: string;
  team: string;
  opponent: string;
  score: string; // team's score, e.g. "3-1"
  key: string; // Faker's game sequence as engine keys: "a" = win, "b" = loss
  games: FakerGame[];
}

export const FAKER_SERIES = data as FakerSeries[];

export const seriesId = (s: FakerSeries) => `${s.date}|${s.opponent}`;

const byKey = new Map<string, FakerSeries[]>();
for (const s of FAKER_SERIES) {
  const list = byKey.get(s.key) ?? [];
  list.push(s);
  byKey.set(s.key, list);
}

// newest first
export function seriesFor(key: string): FakerSeries[] {
  return [...(byKey.get(key) ?? [])].sort((x, y) => y.date.localeCompare(x.date));
}
